def transform(grid):
    h, w = len(grid), len(grid[0])

    # Split at the solid divider.
    for r in range(h):
        if len(set(grid[r])) == 1:
            a = grid[:r]
            b = grid[r + 1:]
            break
    else:
        for c in range(w):
            if len({grid[r][c] for r in range(h)}) == 1:
                a = [row[:c] for row in grid]
                b = [row[c + 1:] for row in grid]
                break

    from collections import Counter

    def bg_and_marks(panel):
        counts = Counter(x for row in panel for x in row)
        bg = counts.most_common(1)[0][0]
        return bg, [[x != bg for x in row] for row in panel]

    bg_a, marks_a = bg_and_marks(a)
    bg_b, marks_b = bg_and_marks(b)

    # Use the panel whose marks match the other panel's background;
    # marks in the other panel erase overlapping marks.
    if any(marks_a[r][c] and grid_color == bg_b
           for r, row in enumerate(a) for c, grid_color in enumerate(row)):
        pass

    fg_a = next((x for row in a for x in row if x != bg_a), None)
    fg_b = next((x for row in b for x in row if x != bg_b), None)

    if fg_a == bg_b:
        main, mask, out_bg = marks_a, marks_b, bg_b
    else:
        main, mask, out_bg = marks_b, marks_a, bg_a

    return [
        [3 if main[r][c] and not mask[r][c] else out_bg
         for c in range(len(main[0]))]
        for r in range(len(main))
    ]
